//! Actual source Host role, filesystem WAV/AssetServer, Source/Rodio/gate/World.
use super::*;
use bevy::audio::Decodable;
use rvn_core::audio_playback::AudioFamily;
type Save=rvn_core::save::consumer_checkpoint::Save15;
const PROGRAM:&str=r#"
init{set hits=0}
function sample(){local draw=random(1,9) return draw}
handler hit(event){flow.consume_v2("handler:hit","call"){set value=sample()} set hits=hits+1}
function paint(state,props,frame){return []}
screen host(context){flow.consume_v2("screen:host","body"){return component("root","column",{},[component("clock","canvas",{"draw":"paint","state":{},"events":{"tick":"hit"}},[])])}}
scene label P
flow.consume_v2("scene:P","seed"){set seed=random(1,9)}
"First"
"after"
"#;
fn source_program(f:&Fixture)->rvn_parser::ParsedProgram{let path=f.root.join("frame.rvn");fs::write(&path,PROGRAM).unwrap();let mut p=rvn_parser::parse_program(&fs::read_to_string(&path).unwrap()).unwrap();p.sources[0].path=Some(path.clone());for o in &mut p.origins{o.source=Some(path.clone());}p}
fn populate_audio(f:&mut Fixture){fs::create_dir_all(f.root.join("assets/music")).unwrap();let music=include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../fixtures/pcm/host.wav"));fs::write(f.root.join("assets/music/host.wav"),music).unwrap();fs::write(f.root.join("assets/host.wav"),music).unwrap();for dir in ["sfx","voice"]{fs::create_dir_all(f.root.join("assets").join(dir)).unwrap();}fs::write(f.root.join("assets/sfx/host.wav"),include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../fixtures/pcm/host.wav"))).unwrap();fs::write(f.root.join("assets/voice/voice.wav"),include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../fixtures/pcm/voice.wav"))).unwrap();f.app.init_asset::<AudioSource>().init_asset_loader::<bevy::audio::AudioLoader>().init_asset::<crate::checkpoint_pcm::CheckpointPcm>().init_resource::<crate::resources::MusicEntity>().init_resource::<crate::resources::MusicAssetRegistry>().init_resource::<crate::resources::ScriptErrorMessage>().init_resource::<crate::scene_audio::AudioFeedbackQueue>();}
fn install_sources(f:&mut Fixture){let deadline=Instant::now()+Duration::from_secs(15);loop{f.app.update();let game=&f.app.world().resource::<VnEngine>().0;match crate::checkpoint_sources::prepare(f.app.world(),&game.state,game.runtime_epoch()).unwrap(){Some(plan)=>{crate::checkpoint_sources::publish(f.app.world_mut(),&plan).unwrap();crate::checkpoint_sources::install(f.app.world_mut(),plan);break;},None=>{}}assert!(Instant::now()<deadline);std::thread::sleep(Duration::from_millis(2));}}
fn host_setup(f:&mut Fixture,p:&rvn_parser::ParsedProgram,french:bool){populate_audio(f);let previous=&f.app.world().resource::<VnEngine>().0;let mut locale=previous.locale.as_ref().unwrap().clone();locale.set_language(if french{"fr"}else{"en"}).unwrap();let mut game=Engine::from_program_with_persistent_and_text_context(p.clone(),BevyRenderer::new(),16,HashMap::new(),rvn_core::TextRuntimeContext::new(previous.text_resources().clone(),Some(locale))).unwrap();game.step_until_interaction().unwrap();game.synchronize_source_menu(rvn_ui::PageRole::Pause,Some("host"),rvn_parser::Value::Dict(Default::default()),true,500).unwrap();let instance=game.state.ui.screens.iter().find(|i|i.name=="host").unwrap();let owner=rvn_core::scene_tasks::TaskOwner::Host{role:instance.host_role.unwrap().id().into()};let epoch=game.runtime_epoch();for(family,file)in [(AudioFamily::Sfx,"sfx/host.wav"),(AudioFamily::Voice,"voice/voice.wav")]{rvn_core::audio_playback::register(&mut game.state,epoch,owner.clone(),rvn_core::audio_playback::AudioPlayback::new(family,file.into(),0.0).unwrap()).unwrap();}if let Some(file)=game.state.music.current_file.clone(){
    use rvn_core::{retired_presentations::{RetiredPresentation,RetiredModel,PresentationSlot},scene_resources::{TargetKind,SavedEffect,EffectClock,EffectParameters}};
    let original=game.state.scene_execution.as_ref().unwrap().resources.targets.iter().find(|r|r.identity.kind==TargetKind::Music).unwrap().clone();let volume=game.state.music.volume;
    rvn_core::scene_resources::register_retired_effect(&mut game.state,epoch,owner.clone(),RetiredPresentation{original_slot:PresentationSlot::Music,original_target:original,model:RetiredModel::Music{file,volume,fade:None}},SavedEffect{presentation:None,base_resolved:false,clock:EffectClock{duration:1.0,elapsed:0.0,looping:false},parameters:EffectParameters::AudioFade{from:1.0,to:0.0,despawn_on_done:true}}).unwrap().unwrap();
}f.app.world_mut().insert_resource(VnEngine(game));f.app.world_mut().resource_mut::<crate::systems::settings_menu::Settings>().language=if french{"fr"}else{"en"}.into();install_sources(f);crate::scene_publication::consume(f.app.world_mut());assert!(!f.app.world().resource::<VnEngine>().0.renderer.scene_batch_pending());}
fn breakpoint(p:&rvn_parser::ParsedProgram)->rvn_core::editor_debugger::Breakpoint{let prepared=rvn_core::program::PreparedNarrative::from_parsed(p.clone()).unwrap();let pc=prepared.script.iter().position(|s|matches!(s,rvn_parser::Statement::Function{name,..}if name=="sample")).unwrap();rvn_core::editor_debugger::Breakpoint{position:prepared.position(pc),site:Some(rvn_core::editor_debugger::Site{function:Some("sample".into()),route:vec![rvn_core::editor_debugger::Route::Statement(1)],depth:2,statement:true}),enabled:true}}
fn captured()->(Fixture,rvn_parser::ParsedProgram,Save){let(mut f,p,_,_)=atomic_save_fixture();let p={let _=p;source_program(&f)};host_setup(&mut f,&p,true);let views=f.app.world().resource::<VnEngine>().0.audio_playback_views().unwrap();for view in &views{let reader=crate::checkpoint_sources::one_shot_source(f.app.world(),&view.token.target).unwrap().0;let mut source=reader.decoder();let count=if view.playback.family==AudioFamily::Sfx{3}else{5};assert_eq!(source.by_ref().take(count).count(),count);}
    let mut game=f.app.world_mut().resource_mut::<VnEngine>();let mut session=game.0.debug_begin(rvn_core::engine::DebugOperation::HostFrame{seconds:0.1,reports:Default::default(),audio:vec![]},vec![breakpoint(&p)]).unwrap();assert_eq!(game.0.debug_step(&mut session,rvn_core::editor_debugger::StepKind::Continue).unwrap().0,rvn_core::engine::DebugProgress::Stopped);let save=game.0.capture_save15(&p,Some(&session),39,"all rows real Host cursor".into()).unwrap();drop(game);(f,p,Save::decode(&save.encode().unwrap()).unwrap())}
#[test]
fn actual_frame_broker_captures_both_host_readers_and_story_capture_remains_empty(){let(f,_,_)=captured();let game=&f.app.world().resource::<VnEngine>().0;let story=game.renderer.audio_checkpoints.capture(&game.state,game.instance_id(),game.runtime_epoch()).unwrap();assert!(story.rows.is_empty());let frame=game.renderer.audio_checkpoints.capture_frame(&game.state,game.instance_id(),game.runtime_epoch()).unwrap();assert_eq!(frame.rows.len(),2);let positions:Vec<_>=frame.rows.iter().map(|r|(r.checkpoint.next_sample,r.checkpoint.next_channel)).collect();assert!(positions.contains(&(3,1)));assert!(positions.contains(&(5,1)));}
#[test]
fn cold_actual_world_frame_with_host_context_restores_french_and_exact_voice_channel(){let(source,p,save)=captured();let(mut cold,_,_,_)=atomic_save_fixture();host_setup(&mut cold,&p,false);let context=crate::atomic_text_restore::capture_host_context(cold.app.world(),&p).unwrap();let mut expected=portable_receipt(cold.app.world()).unwrap();expected.locales=save.locale.as_ref().unwrap().clone();let before=atomic_world_before(&cold);let entities=cold.app.world().entities().len();let deadline=Instant::now()+Duration::from_secs(15);let plan=loop{match crate::atomic_text_restore::prepare_with_host_context(cold.app.world(),&p,save.clone(),&expected,&context){Ok(p)=>break p,Err(e)if e.contains("still loading")=>{},Err(e)=>panic!("Actual frame prepare refused: {e}")};cold.app.update();assert!(Instant::now()<deadline);};assert_eq!(atomic_world_before(&cold),before);assert_eq!(cold.app.world().entities().len(),entities);let resumed=crate::atomic_text_restore::commit(cold.app.world_mut(),plan).unwrap().expect("Real Frame continuation restored");let _=resumed;let game=&cold.app.world().resource::<VnEngine>().0;assert_eq!(game.locale.as_ref().unwrap().current_lang(),"fr");let voice=game.audio_playback_views().unwrap().into_iter().find(|v|v.playback.family==AudioFamily::Voice).unwrap();let reader=crate::checkpoint_sources::one_shot_source(cold.app.world(),&voice.token.target).unwrap().0;let cp=reader.gate().snapshot(&[&reader],|mut r|Ok(r.remove(0))).unwrap();assert_eq!((cp.next_sample,cp.next_channel),(5,1));let mut decoder=reader.decoder();assert_eq!([decoder.next(),decoder.next()],[Some(0),Some(105)]);drop(source);}
#[test]
fn frame_snapshot_omission_duplicate_foreign_epoch_and_stopped_reader_are_atomic(){
    let(f,_,_)=captured();let game=&f.app.world().resource::<VnEngine>().0;let broker=&game.renderer.audio_checkpoints;let before=serde_json::to_value(&game.state).unwrap();let snapshot=broker.capture_frame(&game.state,game.instance_id(),game.runtime_epoch()).unwrap();
    for mode in 0..4{let mut bad=snapshot.clone();match mode{0=>{bad.rows.pop();},1=>bad.rows.push(bad.rows[0].clone()),2=>bad.instance_id+=1,_=>bad.runtime_epoch+=1};assert!(rvn_core::frame_audio_checkpoint::checkpointed_frame_state(&game.state,game.instance_id(),game.runtime_epoch(),&bad).is_err());assert_eq!(serde_json::to_value(&game.state).unwrap(),before);}
    let reader=crate::checkpoint_sources::one_shot_source(f.app.world(),&snapshot.rows[0].token.target).unwrap().0;reader.stop().unwrap();assert!(broker.capture_frame(&game.state,game.instance_id(),game.runtime_epoch()).is_err());assert_eq!(serde_json::to_value(&game.state).unwrap(),before);
}
#[test]
fn stale_real_host_context_refuses_before_world_and_old_voice_keeps_its_cursor(){
    let(source,p,save)=captured();let(mut cold,_,_,_)=atomic_save_fixture();host_setup(&mut cold,&p,false);let context=crate::atomic_text_restore::capture_host_context(cold.app.world(),&p).unwrap();let mut expected=portable_receipt(cold.app.world()).unwrap();expected.locales=save.locale.as_ref().unwrap().clone();cold.app.world_mut().resource_mut::<VnEngine>().0.state.vars.insert("actual_change".into(),rvn_parser::Value::Int(1));let target=cold.app.world().resource::<VnEngine>().0.audio_playback_views().unwrap().into_iter().find(|v|v.playback.family==AudioFamily::Voice).unwrap().token.target;let reader=crate::checkpoint_sources::one_shot_source(cold.app.world(),&target).unwrap().0;let cp=reader.gate().snapshot(&[&reader],|mut rows|Ok(rows.remove(0))).unwrap();let before=atomic_world_before(&cold);let entities=cold.app.world().entities().len();assert!(crate::atomic_text_restore::prepare_with_host_context(cold.app.world(),&p,save,&expected,&context).is_err());assert_eq!(atomic_world_before(&cold),before);assert_eq!(cold.app.world().entities().len(),entities);assert_eq!(reader.gate().snapshot(&[&reader],|mut rows|Ok(rows.remove(0))).unwrap(),cp);drop(source);
}
#[test]
fn changed_actual_host_pcm_after_preparation_refuses_before_core_language_or_ecs(){
    let(source,p,save)=captured();let(mut cold,_,_,_)=atomic_save_fixture();host_setup(&mut cold,&p,false);let context=crate::atomic_text_restore::capture_host_context(cold.app.world(),&p).unwrap();let mut expected=portable_receipt(cold.app.world()).unwrap();expected.locales=save.locale.as_ref().unwrap().clone();let plan=crate::atomic_text_restore::prepare_with_host_context(cold.app.world(),&p,save,&expected,&context).unwrap();let handle=cold.app.world().resource::<AssetServer>().get_handle::<AudioSource>("voice/voice.wav").unwrap();cold.app.world_mut().resource_mut::<Assets<AudioSource>>().get_mut(handle.id()).unwrap().bytes=std::sync::Arc::from(b"replacement actual Host data".to_vec());let before=atomic_world_before(&cold);let entities=cold.app.world().entities().len();assert!(crate::atomic_text_restore::commit(cold.app.world_mut(),plan).is_err());assert_eq!(atomic_world_before(&cold),before);assert_eq!(cold.app.world().entities().len(),entities);drop(source);
}
#[test]
fn actual_story_and_retired_host_music_have_real_independent_loop_cursors_in_one_frame_fence(){
    let(mut f,_,_,_)=atomic_save_fixture();let path=f.root.join("frame-music.rvn");let text=PROGRAM.replace("scene label P\n","scene label P\nmusic.play(\"host.wav\")\nsfx.play(\"host.wav\")\n");fs::write(&path,&text).unwrap();let mut p=rvn_parser::parse_program(&fs::read_to_string(&path).unwrap()).unwrap();p.sources[0].path=Some(path.clone());for o in &mut p.origins{o.source=Some(path.clone());}host_setup(&mut f,&p,true);let game=&f.app.world().resource::<VnEngine>().0;let music=rvn_core::audio_checkpoint::music_views(&game.state,game.runtime_epoch()).unwrap();assert_eq!(music.len(),2);assert!(music.iter().any(|v|matches!(v.owner,rvn_core::scene_tasks::TaskOwner::Host{..})));
    for view in &music{let entity=crate::checkpoint_sources::music_entity_for_test(f.app.world(),&view.authority.target).unwrap();let handle=f.app.world().get::<Handle<crate::checkpoint_pcm::CheckpointPcm>>(entity).unwrap();let reader=f.app.world().resource::<Assets<crate::checkpoint_pcm::CheckpointPcm>>().get(handle).unwrap();let mut source=reader.decoder();let count=(reader.clip().pcm_bytes()/2)as usize+3;assert_eq!(source.by_ref().take(count).count(),count);}
    let game=&f.app.world().resource::<VnEngine>().0;let all=game.renderer.audio_checkpoints.capture_frame(&game.state,game.instance_id(),game.runtime_epoch()).unwrap();assert_eq!(all.rows.len(),3);assert_eq!(all.music.len(),2);assert!(all.music.iter().all(|m|m.checkpoint.next_sample==3&&m.checkpoint.next_channel==1&&m.checkpoint.looping&&m.checkpoint.loops_completed==1));let story=game.renderer.audio_checkpoints.capture(&game.state,game.instance_id(),game.runtime_epoch()).unwrap();assert_eq!(story.rows.len(),1);assert_eq!(story.music.len(),1);
    let frozen=rvn_core::frame_audio_checkpoint::checkpointed_frame_state(&game.state,game.instance_id(),game.runtime_epoch(),&all).unwrap();assert!(crate::checkpoint_sources::warm_frame_state(f.app.world(),&frozen).unwrap());game.renderer.audio_checkpoints.validate_frame_restore(&frozen).unwrap();
    let mut hot=f.app.world_mut().resource_mut::<VnEngine>();let mut session=hot.0.debug_begin(rvn_core::engine::DebugOperation::HostFrame{seconds:0.1,reports:Default::default(),audio:vec![]},vec![breakpoint(&p)]).unwrap();assert_eq!(hot.0.debug_step(&mut session,rvn_core::editor_debugger::StepKind::Continue).unwrap().0,rvn_core::engine::DebugProgress::Stopped);let save=hot.0.capture_save15(&p,Some(&session),39,"actual looping Host retired music".into()).unwrap();drop(hot);
    let(mut cold,_,_,_)=atomic_save_fixture();host_setup(&mut cold,&p,false);let context=crate::atomic_text_restore::capture_host_context(cold.app.world(),&p).unwrap();let mut expected=portable_receipt(cold.app.world()).unwrap();expected.locales=save.locale.as_ref().unwrap().clone();let before=atomic_world_before(&cold);let plan=crate::atomic_text_restore::prepare_with_host_context(cold.app.world(),&p,save,&expected,&context).unwrap();assert_eq!(atomic_world_before(&cold),before);let mut session=crate::atomic_text_restore::commit(cold.app.world_mut(),plan).unwrap().unwrap();
    let restored=&cold.app.world().resource::<VnEngine>().0;let frame=restored.renderer.audio_checkpoints.capture_frame(&restored.state,restored.instance_id(),restored.runtime_epoch()).unwrap();assert_eq!(frame.music.len(),2);assert!(frame.music.iter().all(|m|m.checkpoint.next_sample==3&&m.checkpoint.next_channel==1&&m.checkpoint.loops_completed==1));assert!(frame.music.iter().any(|row|restored.state.scene_execution.as_ref().unwrap().resources.targets.iter().any(|t|t.identity==row.target&&matches!(t.owner,rvn_core::scene_tasks::TaskOwner::Host{..}))));
    let mut game=cold.app.world_mut().resource_mut::<VnEngine>();for _ in 0..128{let(progress,_)=game.0.debug_step(&mut session,rvn_core::editor_debugger::StepKind::Continue).unwrap();if progress==rvn_core::engine::DebugProgress::Complete{break;}}assert_eq!(game.0.state.vars["hits"],rvn_parser::Value::Int(1));
}
